export function getConnectorKind(kindKey: string) {
  if (kindKey in connectorKindsByKey) {
    return connectorKindsByKey[kindKey as ConnectorKindKey];
  }
  return undefined;
}

export function modulatableChannelsForKind(kindKey: string) {
  const kind = getConnectorKind(kindKey);
  if (!kind) return [];
  return kind.channels.filter((channel) => channel.modulatable);
}
